def link_converted_leads(apps, schema_editor):
    """
    Existing converted leads: link the patient they became. The convert endpoint logged
    "Converted to patient (ID: N)", which is exact; otherwise use the only patient in the
    same clinic with the same phone. Leads with no clear match stay unlinked.
    """
    import re
    Lead = apps.get_model('leads', 'Lead')
    LeadActivity = apps.get_model('leads', 'LeadActivity')
    Patient = apps.get_model('patients', 'Patient')
    for lead in Lead.objects.filter(stage='converted', converted_patient__isnull=True):
        patient, when = None, None
        act = (LeadActivity.objects.filter(lead=lead, note__startswith='Converted to patient (ID:')
               .order_by('-created_at').first())
        if act:
            m = re.search(r'ID:\s*(\d+)', act.note)
            if m:
                patient = Patient.objects.filter(pk=int(m.group(1)), clinic_id=lead.clinic_id).first()
                when = act.created_at
        if patient is None and lead.phone:
            matches = list(Patient.objects.filter(clinic_id=lead.clinic_id, phone=lead.phone)[:2])
            if len(matches) == 1:
                patient = matches[0]
        if patient is not None:
            lead.converted_patient = patient
            lead.converted_at = when or lead.updated_at
            lead.save(update_fields=['converted_patient', 'converted_at'])


